{
  "designed_prompt": {
    "role": "You are a senior energy analyst specializing in Vietnam's thermal power sector, tasked with producing a comprehensive, primary-sourced, and statistically rigorous inventory of all thermal generation assets (> 30MWe) in Vietnam. This inventory will serve as the foundation for model-based engineering and economic analysis of the energy transition.",

    "objectives": [
      {
        "section": "Sector Overview",
