        "schema": {
          "columns": [
            {
              "name": "Name (Vietnamese)",
              "description": "Original Vietnamese name of the plant, including diacritics."
            },
            {
              "name": "Name (English)",
              "description": "English translation or transliteration of the plant name."
            },
            {
              "name": "Province",
              "description": "Province where the plant is or will be located. Use official administrative boundaries."
            },
            {
              "name": "Fuel",
              "description": "Primary fuel type: Coal, Domestic gas, Imported LNG, or Other (specify)."
            },
            {
              "name": "Technology (coal)",
              "description": "Subcritical, Supercritical, or USC. Leave blank if not applicable."
            },
            {
              "name": "Technology (gas)",
              "description": "CCGT or OCGT. Leave blank if not applicable."
            },
            {
              "name": "Units × MW",
              "description": "List of units and their capacities (e.g., '2 × 600 MW, 1 × 300 MW'). Include only units > 30MWe."
            },
            {
              "name": "Total MWe",
              "description": "Sum of all units > 30MWe. Round to the nearest MW."
            },
            {
              "name": "Status",
              "description": "Approved, Planned, Operational, Under construction, Suspended, Cancelled, Retired, or Dismantled. Define each status explicitly in the Notes field if unclear."
            },
            {
              "name": "COD",
              "description": "Actual or expected commercial operation date (YYYY-MM-DD). Use 'unknown' if not specified. For retired plants, include retirement date if available."
            },
            {
              "name": "Owner/Developer",
              "description": "Current owner and/or developer. Include percentage shares if available. Use 'unknown' if not specified."
            },
            {
              "name": "Source 1",
              "description": "Primary source for the plant's existence and key attributes (e.g., government decision, company filing). Include direct URL or document reference."
            },
            {
              "name": "Source 2",
              "description": "Secondary source corroborating the plant's existence or attributes. Include direct URL or document reference."
            },
            {
              "name": "Notes",
              "description": "Qualify any uncertainties, contradictions, or scenario conditions (e.g., 'COD delayed due to financing issues'). Include confidence level (HIGH/MEDIUM/LOW) and rationale. Flag any discrepancies between sources."
